"""Public colleague sign-in/activation shell; no private report data."""


def page(activation=False):
    title = 'Activează contul' if activation else 'Conectare colegi'
    return ('''<!doctype html><html lang="ro"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'''+title+''' · PLUP</title><link rel="stylesheet" href="/auth/style.css"><script src="/auth/member.js" defer></script></head><body><main data-activation="'''+('true' if activation else 'false')+'''"><div class="brand">NRG CABLES · PLUP</div><h1>'''+title+'''</h1><p id="intro">'''+('Se verifică invitația…' if activation else 'Folosește emailul invitat de proprietar și parola ta. Nu ai nevoie de Microsoft sau Teams.')+'''</p><form id="member-form" hidden><label for="email">Email</label><input id="email" type="email" autocomplete="username" maxlength="254" required><label for="password">Parolă</label><input id="password" type="password" minlength="12" maxlength="128" autocomplete="'''+('new-password' if activation else 'current-password')+'''" required><div id="confirmation" hidden><label for="repeat">Repetă parola</label><input id="repeat" type="password" minlength="12" maxlength="128" autocomplete="new-password"></div><button id="submit" type="submit">'''+('Activează și intră în PLUP' if activation else 'Intră în PLUP')+'''</button></form><p id="status" role="status" aria-live="polite"></p><p class="help">'''+('Invitația este individuală, valabilă 48 de ore și poate fi folosită o singură dată.' if activation else 'Ai uitat parola? Cere proprietarului un link nou de activare.')+'''</p><a class="secondary" href="/">Înapoi la conectare</a></main></body></html>''').encode()
